import re

UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_NUM = r'\d+(?:\.\d+)?'
_TOKEN_RE = re.compile(r'\s*(' + _NUM + r')\s*([a-zA-Z]+)\s*')
_ISO_RE = re.compile(
    r'P(?:(' + _NUM + r')W)?(?:(' + _NUM + r')D)?'
    r'(?:T(?:(' + _NUM + r')H)?(?:(' + _NUM + r')M)?(?:(' + _NUM + r')S)?)?',
    re.IGNORECASE,
)


def _finish(total):
    if total < 0:
        raise ValueError("negative duration")
    return int(round(total))


def _parse_iso(text):
    m = _ISO_RE.fullmatch(text)
    if not m or all(g is None for g in m.groups()):
        raise ValueError(f"invalid ISO duration: {text!r}")
    weeks, days, hours, minutes, seconds = (
        float(g) if g is not None else 0.0 for g in m.groups()
    )
    total = (
        weeks * 604800
        + days * 86400
        + hours * 3600
        + minutes * 60
        + seconds
    )
    return _finish(total)


def _parse_clock(text):
    parts = text.split(':')
    if len(parts) not in (2, 3):
        raise ValueError(f"invalid clock notation: {text!r}")
    for p in parts:
        if not re.fullmatch(_NUM, p):
            raise ValueError(f"invalid clock notation: {text!r}")
    values = [float(p) for p in parts]
    if len(values) == 2:
        minutes, seconds = values
        total = minutes * 60 + seconds
    else:
        hours, minutes, seconds = values
        total = hours * 3600 + minutes * 60 + seconds
    return _finish(total)


def _parse_components(text):
    pos = 0
    total = 0.0
    count = 0
    while pos < len(text):
        m = _TOKEN_RE.match(text, pos)
        if not m or m.start() != pos:
            raise ValueError(f"invalid duration: {text!r}")
        num = float(m.group(1))
        unit = m.group(2).lower()
        if unit not in UNITS:
            raise ValueError(f"unknown unit: {unit!r}")
        total += num * UNITS[unit]
        pos = m.end()
        count += 1
    if count == 0:
        raise ValueError(f"invalid duration: {text!r}")
    return _finish(total)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    stripped = text.strip()
    if not stripped:
        raise ValueError("empty input")

    if re.fullmatch(r'\d+', stripped):
        return int(stripped)

    if ':' in stripped:
        return _parse_clock(stripped)

    if stripped[0] in ('P', 'p'):
        return _parse_iso(stripped)

    return _parse_components(stripped)

